import { tags } from "typia";

import { IAuthorizationToken } from "./IAuthorizationToken";

export namespace ITodoAppGuest {
  /**
   * Guest session refresh request containing the current refresh token for token rotation.
   */
  export type IRefresh = {
    /**
     * JWT refresh token from the guest session that needs to be validated and rotated for continued access.
     *
     * @x-autobe-specification Computed: refresh_token is generated by the server and stored in todo_app_guest_sessions table. Used for validating and rotating guest session authentication tokens.
     */
    refresh_token: string;
  };

  /**
   * Request body for guest account registration.
   */
  export type IJoin = {
    /**
     * @x-autobe-database-schema-property device_id
     */
    device_id: string & tags.Format<"uuid">;
    /**
     * @x-autobe-database-schema-property ip
     */
    ip: string & tags.Format<"ipv4">;

    /**
     * Optional browser user agent string for device identification.
     *
     * @x-autobe-database-schema-property user_agent
     * @x-autobe-specification Direct mapping from todo_app_guests.user_agent column. Nullable field for device identification.
     */
    user_agent?: string | null | undefined;
    href?: (string & tags.Format<"uri">) | undefined;
    referrer?: (string & tags.Format<"uri">) | undefined;
  };

  /**
   * Authentication response for guest account registration or session refresh, containing access and refresh tokens for temporary session management.
   */
  export type IAuthorized = {
    /**
     * Unique identifier for the guest account.
     *
     * @x-autobe-database-schema-property id
     * @x-autobe-specification Direct mapping from todo_app_guests.id. UUID identifier for the guest account.
     */
    id: string & tags.Format<"uuid">;

    /**
     * Authorization token.
     *
     * @x-autobe-specification Authorization token comes from the session table.
     */
    token: IAuthorizationToken;
  };
}
